export default {"/lattice.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Lattice & arithmetic — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/lattice.html\">\n<meta name=\"description\" content=\"The register geometry and the exact integer arithmetic every other wing is built on. 9 capabilities; 7 of 7 evidence predicates hold.\">\n<meta property=\"og:title\" content=\"Lattice & arithmetic — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"The register geometry and the exact integer arithmetic every other wing is built on. 9 capabilities; 7 of 7 evidence predicates hold.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/lattice.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Lattice & arithmetic\">\n<meta name=\"twitter:description\" content=\"The register geometry and the exact integer arithmetic every other wing is built on. 9 capabilities; 7 of 7 evidence predicates hold.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>Lattice &amp; arithmetic</h1>\n<p>The register geometry and the exact integer arithmetic every other wing is built on.</p>\n<table>\n<tr><th></th><th></th></tr>\n<tr><td>Capabilities</td><td>9</td></tr>\n<tr><td>With an evidence predicate</td><td>7</td></tr>\n<tr><td>Predicates that hold now</td><td>7</td></tr>\n<tr><td>Live (need the network; checked by the live doors)</td><td>0</td></tr>\n</table>\n<table>\n<tr><th>Capability</th><th>Kind</th><th>What it does</th><th>Evidence</th><th>Status</th></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L286\"><code>chooseOf</code></a></td><td>builder</td><td>Binomial coefficient C(nn, k) by Pascal recursion, mirroring chooseOf in index.lean.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L647\"><code>qpuBalanceOf</code></a></td><td>builder</td><td>The 'balance' reading: theory and practice equal and summing to coins (theorem follow_the_coins).</td><td><code>qpuBalanceHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L3614\"><code>qpuCapacityOf</code></a></td><td>builder</td><td>Capacity counts: bits, amplitudes, fused = faces x 2^(bits+1), next, the crypt split and the agent and schema counts.</td><td><code>qpuCapacityHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L513\"><code>qpuCubeOf</code></a></td><td>builder</td><td>The register geometry: n qubits, vertices = 2^n, hexbit = 2^(n-1), bits = vertices x hexbit.</td><td><code>qpuCubeHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L619\"><code>qpuElectronicsOf</code></a></td><td>builder</td><td>The 'electronics' reading: the coil (coins x rays) used as staged windings, theory and practice each one seed.</td><td><code>qpuElectronicsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L559\"><code>qpuFacesOf</code></a></td><td>builder</td><td>The lattice of faces: coins, rays = n + 2 coins, faces = coins x rays = rays + rays, with the coil derived from them.</td><td><code>qpuFacesHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L527\"><code>qpuHandleOf</code></a></td><td>builder</td><td>Amplitude capacity: amplitudes = 2^bits, next = 2 x amplitudes, and the KV reading of both.</td><td><code>qpuHandleHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L3839\"><code>qpuSpeedOf</code></a></td><td>builder</td><td>The doubling rung: next = fused + fused, with the cover of rungs and a benchmark of the step.</td><td><code>qpuSpeedHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L483\"><code>tenOf</code></a></td><td>builder</td><td>10^k by repeated multiplication (no Math.pow), used for page sizes and deadlines.</td><td>—</td><td>—</td></tr>\n</table>\n<p>Generated from the inline docs by <code>npm run docs</code>. Index: <a href=\"README.html\">docs</a>.</p>\n</body></html>\n","/quantum.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Quantum computation — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/quantum.html\">\n<meta name=\"description\" content=\"Exact integer-amplitude state vectors, the running circuit, Shor and the end-to-end proof. 17 capabilities; 14 of 17 evidence predicates hold.\">\n<meta property=\"og:title\" content=\"Quantum computation — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"Exact integer-amplitude state vectors, the running circuit, Shor and the end-to-end proof. 17 capabilities; 14 of 17 evidence predicates hold.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/quantum.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Quantum computation\">\n<meta name=\"twitter:description\" content=\"Exact integer-amplitude state vectors, the running circuit, Shor and the end-to-end proof. 17 capabilities; 14 of 17 evidence predicates hold.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>Quantum computation</h1>\n<p>Exact integer-amplitude state vectors, the running circuit, Shor and the end-to-end proof.</p>\n<table>\n<tr><th></th><th></th></tr>\n<tr><td>Capabilities</td><td>17</td></tr>\n<tr><td>With an evidence predicate</td><td>17</td></tr>\n<tr><td>Predicates that hold now</td><td>14</td></tr>\n<tr><td>Live (need the network; checked by the live doors)</td><td>3</td></tr>\n</table>\n<table>\n<tr><th>Capability</th><th>Kind</th><th>What it does</th><th>Evidence</th><th>Status</th></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L2798\"><code>qpuCircuitOf</code></a></td><td>builder</td><td>The running 3-qubit circuit on exact integer amplitudes: split, Bell, GHZ, interference, no-clone, teleport, kickback, Deutsch, superdense coding, monogamy; each with its Born weights.</td><td><code>qpuCircuitHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L2032\"><code>qpuComputerOf</code></a></td><td>builder</td><td>The exact state-vector computer: universal gate basis, reset, SWAP, Toffoli, coupling, compile, collapse, shots, feed-forward, bit-flip correction and readout, each step with its check.</td><td><code>qpuComputerHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1777\"><code>qpuDesignOf</code></a></td><td>builder</td><td>Fourteen named design nodes, one per face, each with a synapse fold; vacant must be zero.</td><td><code>qpuDesignHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L5861\"><code>qpuEvidenceOf</code></a></td><td>builder</td><td>Provenance and verification evidence: provider and device (exact-amplitudes), noise, volume, cross-checks, scaling and fault readings.</td><td><code>qpuEvidenceHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L8196\"><code>qpuIdeasOf</code></a></td><td>builder</td><td>The seven ideas the sandbox teams compete on, each as a sealed op tree with its left and right sides.</td><td><code>qpuIdeasHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12715\"><code>qpuImproveLiveOf</code></a></td><td>builder</td><td>qpu_improve with live CERN occupancy.</td><td><code>qpuImproveLiveHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L9053\"><code>qpuImproveOf</code></a></td><td>builder</td><td>Improve by doubling: before and after readings of quality, speed, security and throughoutput, with the unlocked quantum door.</td><td><code>qpuImproveHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L11553\"><code>qpuIntegrityOf</code></a></td><td>builder</td><td>Three integrity tests (quantum, cube, around) plus the CERN records the cern theorem quotes.</td><td><code>qpuIntegrityHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1826\"><code>qpuNeuroOf</code></a></td><td>builder</td><td>A fixed integer network: depth n, width faces, weights from the lattice, one exact forward pass.</td><td><code>qpuNeuroHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12791\"><code>qpuProveLiveOf</code></a></td><td>builder</td><td>qpu_prove after the live sequence.</td><td><code>qpuProveLiveHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L11301\"><code>qpuProveOf</code></a></td><td>builder</td><td>Prove the unit end to end: every Lean row, the Shor run, the circuit steps, the source fold and the evidence block; holds is their conjunction.</td><td><code>qpuProveHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L5724\"><code>qpuPurposeOf</code></a></td><td>builder</td><td>What the unit is for, read from its own state: exact-amplitude platform, n qubits, and its cybersecurity, optimisation, science and sensing readings.</td><td><code>qpuPurposeHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L4808\"><code>qpuQuantumOf</code></a></td><td>builder</td><td>The quantum document: circuit, lattice, Shor run, sequence, purpose, evidence, network and design readings in one JSON-LD document.</td><td><code>qpuQuantumHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L5352\"><code>qpuReadingOf</code></a></td><td>builder</td><td>A compact reading of the quantum document (circuit, lattice, Shor, sequence, purpose, evidence) for agents.</td><td><code>qpuReadingHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12818\"><code>qpuSequenceLiveOf</code></a></td><td>builder</td><td>The live sequence: train, improve, compete and prove, each live.</td><td><code>qpuSequenceLiveHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L5505\"><code>qpuSequenceOf</code></a></td><td>builder</td><td>The learning sequence: rungs, API rows and climb over storage, network and server tools.</td><td><code>qpuSequenceHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L8987\"><code>qpuVmOf</code></a></td><td>builder</td><td>The VM reading: isolate rungs and replicas doubling to next, agents per face.</td><td><code>qpuVmHolds</code></td><td>holds</td></tr>\n</table>\n<p>Generated from the inline docs by <code>npm run docs</code>. Index: <a href=\"README.html\">docs</a>.</p>\n</body></html>\n","/proof.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Formal proof (Lean) — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/proof.html\">\n<meta name=\"description\" content=\"index.lean served theorem by theorem, recomputed and typeset. 12 capabilities; 4 of 4 evidence predicates hold.\">\n<meta property=\"og:title\" content=\"Formal proof (Lean) — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"index.lean served theorem by theorem, recomputed and typeset. 12 capabilities; 4 of 4 evidence predicates hold.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/proof.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Formal proof (Lean)\">\n<meta name=\"twitter:description\" content=\"index.lean served theorem by theorem, recomputed and typeset. 12 capabilities; 4 of 4 evidence predicates hold.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>Formal proof (Lean)</h1>\n<p>index.lean served theorem by theorem, recomputed and typeset.</p>\n<table>\n<tr><th></th><th></th></tr>\n<tr><td>Capabilities</td><td>12</td></tr>\n<tr><td>With an evidence predicate</td><td>4</td></tr>\n<tr><td>Predicates that hold now</td><td>4</td></tr>\n<tr><td>Live (need the network; checked by the live doors)</td><td>0</td></tr>\n</table>\n<table>\n<tr><th>Capability</th><th>Kind</th><th>What it does</th><th>Evidence</th><th>Status</th></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean-eval.ts#L327\"><code>leanArityOf</code></a></td><td>builder</td><td>The arity of a definition: its parameter count (pattern-matched builtins by their transcription).</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean-eval.ts#L121\"><code>leanModelOf</code></a></td><td>builder</td><td>The defs of the Lean source: <code>def x : Nat := e</code> and <code>def f (p q : Nat) : Nat := e</code>.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean-eval.ts#L258\"><code>leanRecomputeOf</code></a></td><td>builder</td><td>Decide one theorem statement exactly, over the stated range when it binds variables, and typeset it.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean-eval.ts#L300\"><code>leanTheoremBlocksOf</code></a></td><td>builder</td><td>Every theorem of the source as [name, text]: the <code>theorem</code> line and its continuation lines, whitespace folded.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L4033\"><code>qpuCrossReadingOf</code></a></td><td>builder</td><td>CROSS is the fifth reading: a statement whose two sides ARE the two readings — a sum of like terms equal to a product of unlike ones. <code>next_fused</code> (faces * mintOf (bits + coins) = fused + fused) is the asymmetric reading set equal to the symmetric one; reading only its right side called it symmetric, which is half of what it says.</td><td><code>qpuCrossReadingHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L15451\"><code>qpuHexDiscoverOf</code></a></td><td>builder</td><td>The formulas discover each other: every Lean formula is evaluated over the lattice's own constants (each 0-arity formula's value, bounded so loops stay small), results are grouped by value, and a value reached by formulas of two or more families is a discovered relation.</td><td><code>qpuHexDiscoverHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L4057\"><code>qpuLeanOf</code></a></td><td>builder</td><td>Every theorem of index.lean as a row: statement verbatim, LaTeX, reading, cross reading, statement UUID and holds recomputed by lean-eval.</td><td><code>qpuLeanHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L3950\"><code>qpuLeanSourceOf</code></a></td><td>builder</td><td>The embedded index.lean: bytes, fold, theorem count, how many served rows are verbatim in it, toolchain pin.</td><td><code>qpuLeanSourceHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L11523\"><code>quantumModeOf</code></a></td><td>builder</td><td>True when the served Lean rows include all_complete, coins_two, around or harmonic, involution, and entangle or monogamy, each holding.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean-eval.ts#L318\"><code>leanCallOf</code></a></td><td>function</td><td>Call one definition of the Lean source by name with natural-number arguments, under Lean's Nat semantics.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean-eval.ts#L336\"><code>leanLinksOf</code></a></td><td>function</td><td>The formulas discover each other: every declaration's statement and proof are read for the other declarations they name.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L3937\"><code>qpuStatementUuidOf</code></a></td><td>function</td><td>The content UUID of a theorem's statement (its type, binders excluded): the address every served row's handle is cut from.</td><td>—</td><td>—</td></tr>\n</table>\n<h2>Lean families</h2>\n<p>index.lean is the bundle of these modules (scripts/lean-bundle.mjs); <code>npm run lean</code> builds the modules with Lake, checks the bundle matches them, and checks the bundle with Lean. Each module with definitions is a hex family: its handle is the fold of its name and each definition is one program nibble.</p>\n<table>\n<tr><th>Module</th><th>Hex handle</th><th>Formulas (nibble: name)</th><th>Theorems</th><th>Uses</th></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean/Qpu/Mint.lean\">Qpu.Mint</a></td><td><code>c8372ae3</code></td><td>1: mintOf, 2: chooseOf</td><td>4</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean/Qpu/Shor.lean\">Qpu.Shor</a></td><td><code>d5716b2a</code></td><td>1: powMod, 2: periodOf, 3: gcdOf, 4: half</td><td>2</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean/Qpu/Lattice.lean\">Qpu.Lattice</a></td><td><code>72af0c7c</code></td><td>1: n, 2: seed, 3: coins, 4: scanner, 5: radar, 6: rays, 7: vertices, 8: hexbit, 9: bits, a: faces, b: amplitudes, c: fused, d: plane</td><td>38</td><td>Mint (50)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean/Qpu/Circuit.lean\">Qpu.Circuit</a></td><td>—</td><td>—</td><td>22</td><td>Mint (17), Lattice (51)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean/Qpu/Hybrid.lean\">Qpu.Hybrid</a></td><td><code>61b7d2d2</code></td><td>1: kvCost, 2: r2Cost, 3: hybridCost, 4: kvSpeed, 5: r2Speed, 6: hybridSpeed</td><td>3</td><td>Lattice (21), Mint (2)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean/Qpu/Coil.lean\">Qpu.Coil</a></td><td><code>a13a4aae</code></td><td>1: theory, 2: practice, 3: coil</td><td>9</td><td>Lattice (39), Mint (5)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean/Qpu/Physics.lean\">Qpu.Physics</a></td><td><code>cf1194df</code></td><td>1: planck, 2: boltzmann, 3: transmon, 4: photon, 5: thermal, 6: bcs, 7: aluminium, 8: niobium, 9: gap</td><td>4</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean/Qpu/Cern.lean\">Qpu.Cern</a></td><td>—</td><td>—</td><td>1</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean/Qpu/Fuse.lean\">Qpu.Fuse</a></td><td>—</td><td>—</td><td>1</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean/Qpu/Cross.lean\">Qpu.Cross</a></td><td>—</td><td>—</td><td>16</td><td>Lattice (73), Mint (8), Coil (2)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/lean/Qpu/Clay.lean\">Qpu.Clay</a></td><td>—</td><td>—</td><td>24</td><td>Lattice (56), Mint (14), Hybrid (2), Coil (2), Shor (4)</td></tr>\n</table>\n<p>133 pairs of definitions are related by at least one theorem. Strongest: mintOf ~ seed (35), coins ~ mintOf (28), mintOf ~ n (25), bits ~ mintOf (24), coins ~ rays (23), faces ~ rays (23).</p>\n<h2>Discovered relations</h2>\n<p>Every formula evaluated over the lattice constants; values reached by formulas of two or more families, each way as a runnable hex program (<code>GET /hex/&lt;uuid></code>).</p>\n<table>\n<tr><th>Value</th><th>Families</th><th>Ways (hex)</th></tr>\n<tr><td>8</td><td>Qpu.Hybrid, Qpu.Lattice, Qpu.Mint, Qpu.Shor</td><td>vertices() <code>72af0c7c-7000-8000-8000-000000000000</code>&lt;br>hybridSpeed() <code>61b7d2d2-6000-8000-8000-000000000000</code>&lt;br>mintOf(3) <code>c8372ae3-1000-8000-9000-000000000003</code></td></tr>\n<tr><td>32</td><td>Qpu.Lattice, Qpu.Mint, Qpu.Shor</td><td>bits() <code>72af0c7c-9000-8000-8000-000000000000</code>&lt;br>mintOf(5) <code>c8372ae3-1000-8000-9000-000000000005</code>&lt;br>powMod(2, 5, 352) <code>d5716b2a-1000-8000-b000-000200050160</code></td></tr>\n<tr><td>14</td><td>Qpu.Coil, Qpu.Lattice</td><td>faces() <code>72af0c7c-a000-8000-8000-000000000000</code>&lt;br>coil() <code>a13a4aae-3000-8000-8000-000000000000</code></td></tr>\n<tr><td>16</td><td>Qpu.Mint, Qpu.Shor</td><td>mintOf(4) <code>c8372ae3-1000-8000-9000-000000000004</code>&lt;br>powMod(2, 7, 28) <code>d5716b2a-1000-8000-b000-00020007001c</code>&lt;br>powMod(2, 4, 32) <code>d5716b2a-1000-8000-b000-000200040020</code></td></tr>\n<tr><td>21</td><td>Qpu.Mint, Qpu.Shor</td><td>chooseOf(7, 2) <code>c8372ae3-2000-8000-a000-000007000002</code>&lt;br>chooseOf(7, 5) <code>c8372ae3-2000-8000-a000-000007000005</code>&lt;br>powMod(7, 2, 28) <code>d5716b2a-1000-8000-b000-00070002001c</code></td></tr>\n<tr><td>25</td><td>Qpu.Physics, Qpu.Shor</td><td>powMod(3, 4, 28) <code>d5716b2a-1000-8000-b000-00030004001c</code>&lt;br>powMod(3, 14, 32) <code>d5716b2a-1000-8000-b000-0003000e0020</code>&lt;br>powMod(3, 28, 28) <code>d5716b2a-1000-8000-b000-0003001c001c</code></td></tr>\n<tr><td>28</td><td>Qpu.Lattice, Qpu.Mint</td><td>plane() <code>72af0c7c-d000-8000-8000-000000000000</code>&lt;br>chooseOf(8, 2) <code>c8372ae3-2000-8000-a000-000008000002</code></td></tr>\n<tr><td>128</td><td>Qpu.Mint, Qpu.Shor</td><td>mintOf(7) <code>c8372ae3-1000-8000-9000-000000000007</code>&lt;br>powMod(2, 7, 352) <code>d5716b2a-1000-8000-b000-000200070160</code>&lt;br>powMod(28, 3, 352) <code>d5716b2a-1000-8000-b000-001c00030160</code></td></tr>\n<tr><td>256</td><td>Qpu.Mint, Qpu.Shor</td><td>mintOf(8) <code>c8372ae3-1000-8000-9000-000000000008</code>&lt;br>powMod(2, 8, 352) <code>d5716b2a-1000-8000-b000-000200080160</code>&lt;br>powMod(2, 28, 352) <code>d5716b2a-1000-8000-b000-0002001c0160</code></td></tr>\n<tr><td>4294967296</td><td>Qpu.Lattice, Qpu.Mint</td><td>amplitudes() <code>72af0c7c-b000-8000-8000-000000000000</code>&lt;br>mintOf(32) <code>c8372ae3-1000-8000-9000-000000000020</code></td></tr>\n</table>\n<p>Generated from the inline docs by <code>npm run docs</code>. Index: <a href=\"README.html\">docs</a>.</p>\n</body></html>\n","/crypto.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Cryptography — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/crypto.html\">\n<meta name=\"description\" content=\"Shor on 91, RSA factoring and the crypt split identity as callable doors. 3 capabilities; 2 of 2 evidence predicates hold.\">\n<meta property=\"og:title\" content=\"Cryptography — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"Shor on 91, RSA factoring and the crypt split identity as callable doors. 3 capabilities; 2 of 2 evidence predicates hold.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/crypto.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Cryptography\">\n<meta name=\"twitter:description\" content=\"Shor on 91, RSA factoring and the crypt split identity as callable doors. 3 capabilities; 2 of 2 evidence predicates hold.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>Cryptography</h1>\n<p>Shor on 91, RSA factoring and the crypt split identity as callable doors.</p>\n<table>\n<tr><th></th><th></th></tr>\n<tr><td>Capabilities</td><td>3</td></tr>\n<tr><td>With an evidence predicate</td><td>2</td></tr>\n<tr><td>Predicates that hold now</td><td>2</td></tr>\n<tr><td>Live (need the network; checked by the live doors)</td><td>0</td></tr>\n</table>\n<table>\n<tr><th>Capability</th><th>Kind</th><th>What it does</th><th>Evidence</th><th>Status</th></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L6089\"><code>qpuCybersecurityOf</code></a></td><td>builder</td><td>The cybersecurity door set: Shor on 91, RSA factoring, the encrypt identity, crypt split and RAID, with what each verifies.</td><td><code>qpuCybersecurityHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L6218\"><code>qpuCybersecurityToolsOf</code></a></td><td>builder</td><td>The eight cybersecurity MCP tools (catalog, rsa, shor, cmodexp, iqft, shots, split, verify) with their man pages and handlers.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L3770\"><code>qpuEncryptOf</code></a></td><td>builder</td><td>The split identity of theorem crypto: fused = split x share, recomputed; secrecy is reported false (it is an identity, not a cipher).</td><td><code>qpuEncryptHolds</code></td><td>holds</td></tr>\n</table>\n<p>Generated from the inline docs by <code>npm run docs</code>. Index: <a href=\"README.html\">docs</a>.</p>\n</body></html>\n","/receipts.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>UUIDs & quantum receipts — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/receipts.html\">\n<meta name=\"description\" content=\"Content-addressed identity and the receipt streams that record every computation. 39 capabilities; 15 of 17 evidence predicates hold.\">\n<meta property=\"og:title\" content=\"UUIDs & quantum receipts — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"Content-addressed identity and the receipt streams that record every computation. 39 capabilities; 15 of 17 evidence predicates hold.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/receipts.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"UUIDs & quantum receipts\">\n<meta name=\"twitter:description\" content=\"Content-addressed identity and the receipt streams that record every computation. 39 capabilities; 15 of 17 evidence predicates hold.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>UUIDs &amp; quantum receipts</h1>\n<p>Content-addressed identity and the receipt streams that record every computation.</p>\n<table>\n<tr><th></th><th></th></tr>\n<tr><td>Capabilities</td><td>39</td></tr>\n<tr><td>With an evidence predicate</td><td>17</td></tr>\n<tr><td>Predicates that hold now</td><td>15</td></tr>\n<tr><td>Live (need the network; checked by the live doors)</td><td>0</td></tr>\n</table>\n<table>\n<tr><th>Capability</th><th>Kind</th><th>What it does</th><th>Evidence</th><th>Status</th></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L9761\"><code>qpuContentUuidOf</code></a></td><td>builder</td><td>RFC 9562 v8 content UUID of any JSON value over canonical JSON (sorted keys); the same content gives the same UUID anywhere.</td><td><code>qpuContentUuidHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L3598\"><code>qpuContextOf</code></a></td><td>builder</td><td>The JSON-LD @context every served document carries (schema.org plus the unit's prefixes).</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L9999\"><code>qpuFieldUuidOf</code></a></td><td>builder</td><td>One field, addressed by what it IS rather than by what it is called: its name and its shape, folded.</td><td><code>qpuFieldUuidHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L51\"><code>qpuFoldOf</code></a></td><td>builder</td><td>FNV-1a 64 fold of a string to 16 lowercase hex digits (BigInt arithmetic); the hash every receipt, ETag and content address in the unit is built on.</td><td><code>qpuFoldHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L15502\"><code>qpuHexCatalogOf</code></a></td><td>builder</td><td>The hex catalogue: every formula family with its handle and formulas by nibble, the param modes, the layout.</td><td><code>qpuHexHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L15388\"><code>qpuHexDecodeOf</code></a></td><td>builder</td><td>Read a hex-program UUID back: its family, its formulas in order, its params.</td><td><code>qpuHexHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L15336\"><code>qpuHexFamiliesOf</code></a></td><td>builder</td><td>Every formula family a hex program can name: each Lean module with definitions (Qpu.Mint, Qpu.Shor, Qpu.Lattice, Qpu.Hybrid, Qpu.Physics; its definitions in file order, helpers ending Aux left out) evaluated exactly under Lean's Nat semantics, and every registered family.</td><td><code>qpuHexHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L15412\"><code>qpuHexRunOf</code></a></td><td>builder</td><td>Run a hex program of formulas.</td><td><code>qpuHexHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L15365\"><code>qpuHexUuidOf</code></a></td><td>builder</td><td>Mint the UUID that is a program of formulas: handle (8 hex) = fold of the family name; three 4-hex program sections hold up to ten formula indexes, one per nibble (version 8 and the variant kept; the variant's two free bits select how the params split); params (12 hex) carry up to three naturals.</td><td><code>qpuHexHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L6517\"><code>qpuMessageOf</code></a></td><td>builder</td><td>Send or read a message on a lane; each message gets an RFC 9562 UUID and a clock sequence.</td><td><code>qpuMessageHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L168\"><code>qpuMintReceiptOf</code></a></td><td>builder</td><td>The mint ledger: number of mintOf calls and the two FNV chains (process-wide and current scope) over every k:x it minted.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L268\"><code>qpuReceiptFoldOf</code></a></td><td>builder</td><td>Fold a list of receipt rows (name:dim:fold) to one 16-hex digest; the proof compares this digest across runs.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L202\"><code>qpuReceiptLedgerOf</code></a></td><td>builder</td><td>The ledger of every quantum computation this process ran, in order.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L231\"><code>qpuReceiptStreamsOf</code></a></td><td>builder</td><td>Every stream replayed from the ledger: each row's prev is the UUID before it (genesis is the stream's href), each UUID recomputes from its payload fold and referrer, and the replayed chain equals the live head's.</td><td><code>qpuReceiptStreamsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L6472\"><code>qpuSeatHandleOf</code></a></td><td>builder</td><td>A seat's handle on a face: its id, href, hop across the involution and the KV capacity it addresses.</td><td><code>qpuSeatHandleHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L14977\"><code>qpuServedLedgerOf</code></a></td><td>builder</td><td>Ledger of memoised documents served, each with the fold of its bytes (its ETag).</td><td><code>qpuServedLedgerHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L15024\"><code>qpuServedMemoOf</code></a></td><td>builder</td><td>The served-document memo: entries, cap and integrity check.</td><td><code>qpuServedMemoHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L9727\"><code>qpuShapeUuidOf</code></a></td><td>builder</td><td>A UUID COMPUTED FROM CONTENT, WHICH IS WHAT MAKES ONE PROGRAMMABLE. uuidImprintOf mints: it counts a sequence and lays the lattice into RFC 9562 fields, so two calls differ.</td><td><code>qpuShapeUuidHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L2734\"><code>qpuShorReceiptsOf</code></a></td><td>builder</td><td>The receipts of one Shor run: the folds, and the exact amplitudes of the modexp and noise states, the ledger gained after <code>from</code>.</td><td><code>qpuShorReceiptsHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L215\"><code>qpuUuidReceiptOf</code></a></td><td>builder</td><td>Append a quantum receipt for a UUID-addressed computation: payload fold of {name, subject, value}; receipt UUID = content UUID of {payload fold, referrer}; chained per stream (seq, prev).</td><td><code>qpuUuidReceiptHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid.ts#L269\"><code>allInDomain</code></a></td><td>function</td><td>Every UUID registered in a domain.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid.ts#L278\"><code>allOfType</code></a></td><td>function</td><td>Every UUID registered with a type.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/mcp/uuid-programmable-core.ts#L270\"><code>consolidatedMCP</code></a></td><td>function</td><td>The ConsolidatedMCP singleton.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid-bridge.ts#L162\"><code>executeByName</code></a></td><td>function</td><td>Execute operation by name (global)</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid-bridge.ts#L153\"><code>executeByUUID</code></a></td><td>function</td><td>Execute operation by UUID (global)</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid.ts#L224\"><code>find</code></a></td><td>function</td><td>The registry entry for a domain and resource.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid.ts#L233\"><code>gen</code></a></td><td>function</td><td>A UUID for a domain and resource: content-derived, or random when asked.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid.ts#L215\"><code>get</code></a></td><td>function</td><td>The registry entry for a UUID.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid.ts#L251\"><code>inDomain</code></a></td><td>function</td><td>Whether a UUID is registered in a domain.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid.ts#L260\"><code>ofType</code></a></td><td>function</td><td>Whether a UUID is registered with a type.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L15322\"><code>qpuHexRegisterOf</code></a></td><td>function</td><td>Register a formula in a family (cross, audit, path, fuse) so a hex UUID can run it; formulas are indexed in name order.</td><td><code>qpuHexHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid.ts#L200\"><code>register</code></a></td><td>function</td><td>Register a resource under a UUID with its type, domain and metadata.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid.ts#L287\"><code>summary</code></a></td><td>function</td><td>Registry counts: total, domains, per type, verified.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid.ts#L189\"><code>uuid</code></a></td><td>function</td><td>The process-wide UUID registry.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid-bridge.ts#L146\"><code>uuidBridge</code></a></td><td>function</td><td>The UUIDBridge singleton.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid.ts#L242\"><code>verify</code></a></td><td>function</td><td>Whether a string has RFC 9562 UUID shape.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/mcp/uuid-programmable-core.ts#L20\"><code>ConsolidatedMCP</code></a></td><td>class</td><td>Operations and workflows addressed by content UUID: executeByUUID, executeProgram (a list of UUIDs, each receipt the next referrer), runDeploymentGate (every operation resolves and qpu_prove holds) and release checks that read npm, GitHub and Zenodo.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid.ts#L42\"><code>UUID</code></a></td><td>class</td><td>The UUID registry: register resources by UUID and index them by domain, resource and type; deterministic() gives content UUIDs (qpuShapeUuidOf).</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/core/uuid-bridge.ts#L31\"><code>UUIDBridge</code></a></td><td>class</td><td>Addresses every core operation by its content UUID (registered in the UUID registry) and executes it by UUID, with a quantum receipt per execution.</td><td>—</td><td>—</td></tr>\n</table>\n<p>Generated from the inline docs by <code>npm run docs</code>. Index: <a href=\"README.html\">docs</a>.</p>\n</body></html>\n","/storage.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Storage & database — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/storage.html\">\n<meta name=\"description\" content=\"RAID over Cloudflare KV and R2, content-addressed storage and the MongoDB-semantics document database. 25 capabilities; 6 of 10 evidence predicates hold.\">\n<meta property=\"og:title\" content=\"Storage & database — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"RAID over Cloudflare KV and R2, content-addressed storage and the MongoDB-semantics document database. 25 capabilities; 6 of 10 evidence predicates hold.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/storage.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Storage & database\">\n<meta name=\"twitter:description\" content=\"RAID over Cloudflare KV and R2, content-addressed storage and the MongoDB-semantics document database. 25 capabilities; 6 of 10 evidence predicates hold.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>Storage &amp; database</h1>\n<p>RAID over Cloudflare KV and R2, content-addressed storage and the MongoDB-semantics document database.</p>\n<table>\n<tr><th></th><th></th></tr>\n<tr><td>Capabilities</td><td>25</td></tr>\n<tr><td>With an evidence predicate</td><td>10</td></tr>\n<tr><td>Predicates that hold now</td><td>6</td></tr>\n<tr><td>Live (need the network; checked by the live doors)</td><td>0</td></tr>\n</table>\n<table>\n<tr><th>Capability</th><th>Kind</th><th>What it does</th><th>Evidence</th><th>Status</th></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/docdb.ts#L344\"><code>docDbOf</code></a></td><td>builder</td><td>A database: named collections over one store, one id function and one write hook.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/db/payload-qpu.ts#L52\"><code>filterOf</code></a></td><td>builder</td><td>Payload's where, operator for operator, as a docdb filter.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L7113\"><code>qpuDocDbOf</code></a></td><td>builder</td><td>The QPU document database (MongoDB query and update semantics, docdb.ts) over the unit's store; ids are content UUIDs; every write is a quantum receipt in the db stream.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1575\"><code>qpuPayloadDbOf</code></a></td><td>builder</td><td>How Payload's database maps onto the hybrid store: KV upper layer, R2 lower layer, collections and the speed/cost readings (theorem hybrid).</td><td><code>qpuPayloadDbHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1271\"><code>qpuRaidOf</code></a></td><td>builder</td><td>RAID 10 over the faces: rays stripes mirrored by coins teams, cheapest-first placement for a given traffic.</td><td><code>qpuRaidHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L6788\"><code>qpuStorageAddressOf</code></a></td><td>builder</td><td>THE KEY IS THE CONTENT, SO THE ADDRESS MUST SEPARATE CONTENT.</td><td><code>qpuStorageAddressHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L7452\"><code>qpuStorageListOf</code></a></td><td>builder</td><td>qpuStorageListOf(env, prefix, limit) → the link names under a prefix in ascending order (so a name that begins with an inverted arrival time lists the newest first), each with the document a GET of it returns; RAID shares and inode keys never list.</td><td><code>qpuStorageListHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L7335\"><code>qpuStorageMaintainOf</code></a></td><td>builder</td><td>Repair broken RAID shares and delete orphans (a write; needs the write token).</td><td><code>qpuStorageMaintainHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L7783\"><code>qpuStorageMcpOf</code></a></td><td>builder</td><td>The storage sub-server's catalogue and live store reading.</td><td><code>qpuStorageMcpHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L7127\"><code>qpuStorageMetaOf</code></a></td><td>builder</td><td>Storage description: memory or KV, RAID, hybrid layers, Payload database mapping, Alpine overlay and bindings.</td><td><code>qpuStorageMetaHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L7176\"><code>qpuStorageMonitorOf</code></a></td><td>builder</td><td>Monitor RAID health: expected and missing shares, incomplete keys, sampled bytes and traffic.</td><td><code>qpuStorageMonitorHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L7483\"><code>qpuStorageOf</code></a></td><td>builder</td><td>Content-addressed storage: GET/PUT/DELETE by key with inodes, referrer links, nlink counting and RAID striping over KV and R2.</td><td><code>qpuStorageHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L7716\"><code>qpuStorageToolsOf</code></a></td><td>builder</td><td>The storage MCP tools (get, list, put, delete, maintain, monitor) bound to an environment and an auth header.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L7440\"><code>qpuStorageWriteAllowedOf</code></a></td><td>builder</td><td>Whether a public write is allowed: only when QPU_WRITE_TOKEN is bound and the bearer matches; fails closed.</td><td><code>qpuStorageWriteAllowedHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/docdb.ts#L177\"><code>applyUpdate</code></a></td><td>function</td><td>Apply a MongoDB update document (operators or a replacement) to a copy of a document; inserting enables $setOnInsert.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/docdb.ts#L103\"><code>compareValues</code></a></td><td>function</td><td>MongoDB comparison order across types: null/undefined &lt; numbers &lt; strings &lt; objects &lt; arrays &lt; booleans; arrays element-wise.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/db/payload-qpu.ts#L37\"><code>down</code></a></td><td>function</td><td>—</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/docdb.ts#L161\"><code>matches</code></a></td><td>function</td><td>Whether a document matches a MongoDB filter (operators, $and/$or/$nor, dotted paths through arrays).</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/docdb.ts#L218\"><code>project</code></a></td><td>function</td><td>Apply an include or exclude projection to a document.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/db/payload-qpu.ts#L33\"><code>up</code></a></td><td>function</td><td>—</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/docdb.ts#L249\"><code>DocCollection</code></a></td><td>class</td><td>One collection over a DocStore: insert, find with sort/skip/limit/projection, count, distinct, update (with upsert), replace and delete.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/docdb.ts#L363\"><code>d1DocStore</code></a></td><td>store</td><td>A document store on a D1 binding: one key/value table, prefix listing by range, so it never scans past its prefix.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/docdb.ts#L36\"><code>memoryDocStore</code></a></td><td>store</td><td>An in-memory DocStore (JSON-serialised values), for tests and Node.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L7098\"><code>qpuDocStoreOf</code></a></td><td>store</td><td>THE QPU AS A DATABASE.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/db/payload-qpu.ts#L148\"><code>qpuAdapter</code></a></td><td>adapter</td><td>Payload database adapter on the QPU document database.</td><td>—</td><td>—</td></tr>\n</table>\n<p>Generated from the inline docs by <code>npm run docs</code>. Index: <a href=\"README.html\">docs</a>.</p>\n</body></html>\n","/agents.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>MCP & agents — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/agents.html\">\n<meta name=\"description\" content=\"The MCP server, its tools and man pages, the sandbox, training and competition doors. 76 capabilities; 45 of 54 evidence predicates hold.\">\n<meta property=\"og:title\" content=\"MCP & agents — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"The MCP server, its tools and man pages, the sandbox, training and competition doors. 76 capabilities; 45 of 54 evidence predicates hold.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/agents.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"MCP & agents\">\n<meta name=\"twitter:description\" content=\"The MCP server, its tools and man pages, the sandbox, training and competition doors. 76 capabilities; 45 of 54 evidence predicates hold.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>MCP &amp; agents</h1>\n<p>The MCP server, its tools and man pages, the sandbox, training and competition doors.</p>\n<table>\n<tr><th></th><th></th></tr>\n<tr><td>Capabilities</td><td>76</td></tr>\n<tr><td>With an evidence predicate</td><td>54</td></tr>\n<tr><td>Predicates that hold now</td><td>45</td></tr>\n<tr><td>Live (need the network; checked by the live doors)</td><td>2</td></tr>\n</table>\n<table>\n<tr><th>Capability</th><th>Kind</th><th>What it does</th><th>Evidence</th><th>Status</th></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L3825\"><code>cryptoClaimOf</code></a></td><td>builder</td><td>The crypto claim READ from the run: the split identity holds and secrecy does not.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L273\"><code>mintOf</code></a></td><td>builder</td><td>The lattice's doubling, exported so nothing has to re-implement it.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1630\"><code>qpuAlpineOf</code></a></td><td>builder</td><td>Native Alpine Linux storage. musl. busybox. overlayfs — KV upper, R2 lower, KV work.</td><td><code>qpuAlpineHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L9870\"><code>qpuCallUuidOf</code></a></td><td>builder</td><td>qpuCallUuidOf(door, left, right) → the address of that combination, as an RFC 9562 v8 UUID.</td><td><code>qpuCallUuidHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L721\"><code>qpuClayOf</code></a></td><td>builder</td><td>2×7 coins = 1+6 coils = clay.</td><td><code>qpuClayHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1692\"><code>qpuCoilEfficiencyOf</code></a></td><td>builder</td><td>Measure coil efficiency in RAID clusters.</td><td><code>qpuCoilEfficiencyHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L573\"><code>qpuCoilOf</code></a></td><td>builder</td><td>Two coins make a coil.</td><td><code>qpuCoilHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L9829\"><code>qpuCombinatorialDoorsOf</code></a></td><td>builder</td><td>The door table, with collisions RECOMPUTED rather than assumed — two names can fold to one hex.</td><td><code>qpuCombinatorialDoorsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12749\"><code>qpuCompeteLiveOf</code></a></td><td>builder</td><td>qpu_compete with live CERN occupancy.</td><td><code>qpuCompeteLiveHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L11219\"><code>qpuCompeteOf</code></a></td><td>builder</td><td>The read team against the call team on quality, speed and security per token; the winner calls qpu_prove.</td><td><code>qpuCompeteHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L14611\"><code>qpuDevelopOf</code></a></td><td>builder</td><td>The develop reading: source, host, tools, API and integrity, for contributors.</td><td><code>qpuDevelopHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L4716\"><code>qpuDocsOf</code></a></td><td>builder</td><td>The unit's inline guide: abstract, API rows, formulas and the learning ladder, as one document.</td><td><code>qpuDocsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1032\"><code>qpuDryOf</code></a></td><td>builder</td><td>Coordinated dry-clean: two teams, occupancy pentagram, genesis coins.</td><td><code>qpuDryHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L5427\"><code>qpuEfficiencyOf</code></a></td><td>builder</td><td>Token efficiency of each door: bytes and tokens to read the tree versus to call the tool.</td><td><code>qpuEfficiencyHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L953\"><code>qpuFollowOf</code></a></td><td>builder</td><td>theorem follow_the_coins</td><td><code>qpuFollowHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L8815\"><code>qpuForgeOf</code></a></td><td>builder</td><td>Forge a tool from a sealed op tree; { name, run, args } forges and evaluates in one call, { uuid, args } runs a forged tool by its content UUID.</td><td><code>qpuForgeHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L4789\"><code>qpuGlossaryOf</code></a></td><td>builder</td><td>WHAT THE WORDS MEAN, SERVED BESIDE THEM. <code>holds</code> is said of every record and means that the record is self-consistent and recomputes to itself; it is not a claim that the test the record describes passed.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13011\"><code>qpuHarnessesOf</code></a></td><td>builder</td><td>INTEGRATE IN ANY HARNESS (the captain, 2026-09-12).</td><td><code>qpuHarnessesHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12918\"><code>qpuHostsOf</code></a></td><td>builder</td><td>MCP hosts the unit is reachable from: fourteen agent harnesses and fourteen LLM clients, one per face.</td><td><code>qpuHostsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1398\"><code>qpuHybridOf</code></a></td><td>builder</td><td>Measure hybrid storage speed and cost.</td><td><code>qpuHybridHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13326\"><code>qpuInstallManifestOf</code></a></td><td>builder</td><td>install.json, served and written from one function so host and file agree.</td><td><code>qpuInstallManifestHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13883\"><code>qpuInstallOf</code></a></td><td>builder</td><td>Interactive install: steps, choices per occupancy and the combinations they make.</td><td><code>qpuInstallHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L5107\"><code>qpuManOf</code></a></td><td>builder</td><td>A tool's man page (NAME, SYNOPSIS, DESCRIPTION, SEE ALSO) for the /mcp door.</td><td><code>qpuManHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L14419\"><code>qpuMcpCallOf</code></a></td><td>builder</td><td>Dispatch one MCP tools/call by name with arguments and shape the reply for MCP clients.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13043\"><code>qpuMcpDiscoverOf</code></a></td><td>builder</td><td>MCP discovery reply: protocol version, capabilities, tools, server info, instructions and install entries.</td><td><code>qpuMcpDiscoverHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L14334\"><code>qpuMcpOf</code></a></td><td>builder</td><td>The MCP catalogue at /mcp: tools, cybersecurity tools, capacity and provider as one JSON-LD WebAPI.</td><td><code>qpuMcpHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L5182\"><code>qpuMcpShownOf</code></a></td><td>builder</td><td>THE REPLY ON THE WIRE, ONCE AS TEXT AND ONCE AS STRUCTURE.</td><td><code>qpuMcpShownHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L14314\"><code>qpuMcpToolsListOf</code></a></td><td>builder</td><td>THE CONNECT BILL (the captain, 2026-09-12: \"minimise bills of any kind\"). tools/list is paid by every client on every connect, in context tokens: the sixteen output schemas were 34,232 of its 44,197 bytes — three quarters of the bill for a document a client validates a reply against at most once.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L178\"><code>qpuMintScopeOpenOf</code></a></td><td>builder</td><td>Start a fresh scope chain and answer the one just closed, so a caller can bracket a region and fold only it.</td><td><code>qpuMintScopeOpenHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10730\"><code>qpuMixedOf</code></a></td><td>builder</td><td>The domains crossed against each other, as unordered pairs of the vocabulary the experiments name.</td><td><code>qpuMixedHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13365\"><code>qpuMountsOf</code></a></td><td>builder</td><td>Every mount this unit offers on the host that asked, plus the zone's other MCP, named and not claimed.</td><td><code>qpuMountsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10758\"><code>qpuNatureOf</code></a></td><td>builder</td><td>IS EVERYTHING ENTANGLED BY NATURE? — the claim, stated precisely enough to be wrong.</td><td><code>qpuNatureHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L7946\"><code>qpuNetworkMcpOf</code></a></td><td>builder</td><td>The network sub-server's catalogue.</td><td><code>qpuNetworkMcpHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L7820\"><code>qpuNetworkToolsOf</code></a></td><td>builder</td><td>The network MCP tools (send, receive, fetch on the named host) for channels in memory.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L675\"><code>qpuNextOf</code></a></td><td>builder</td><td>Next is the double.</td><td><code>qpuNextHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13209\"><code>qpuOccupantOf</code></a></td><td>builder</td><td>Which seat occupies the unit for a referrer, and why.</td><td><code>qpuOccupantHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L5130\"><code>qpuOutputSchemaOf</code></a></td><td>builder</td><td>A JSON Schema derived from a tool's own replies: properties typed from the samples, required = keys present in every sample.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13699\"><code>qpuPayloadPluginOf</code></a></td><td>builder</td><td>Payload extends like a plugin.</td><td><code>qpuPayloadPluginHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L5676\"><code>qpuPlanesOf</code></a></td><td>builder</td><td>PLANES (the captain, 2026-09-12). theorem planes: plane = coins·coins·rays is less than mintOf(rays + seed), and coins·rays = faces.</td><td><code>qpuPlanesHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13143\"><code>qpuPriorArtOf</code></a></td><td>builder</td><td>Prior-art references the router cites, each with its kind (reference, vector, device).</td><td><code>qpuPriorArtHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L14732\"><code>qpuReadmeOf</code></a></td><td>builder</td><td>THE README IS THE npm PAGE.</td><td><code>qpuReadmeHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13232\"><code>qpuRouterOf</code></a></td><td>builder</td><td>Route a referrer and path to a seat and door.</td><td><code>qpuRouterHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L8915\"><code>qpuSandboxDurabilityOf</code></a></td><td>builder</td><td>Sandbox durability: rounds of put/get, fs and net shims and worker isolation, each checked to persist in memory and stay isolated.</td><td><code>qpuSandboxDurabilityHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L8618\"><code>qpuSandboxEpochOf</code></a></td><td>builder</td><td>The sandbox's write epoch: advances when a forge changes a tool, so memoised readings of the sandbox refresh.</td><td><code>qpuSandboxEpochHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L8721\"><code>qpuSandboxOf</code></a></td><td>builder</td><td>The in-memory sandbox census: ops, host shims (all in memory), heap, forged tools; nothing touches disk, network or eval.</td><td><code>qpuSandboxHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L8784\"><code>qpuSandboxRunOf</code></a></td><td>builder</td><td>Run a sandbox tool by name with arguments; the run is a quantum receipt in the sandbox stream.</td><td><code>qpuSandboxRunHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13273\"><code>qpuSeatOf</code></a></td><td>builder</td><td>The seat record: how to install and run the unit (command, packages, Cloudflare button).</td><td><code>qpuSeatHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13162\"><code>qpuSeatsAvailableOf</code></a></td><td>builder</td><td>THE UNIT AS A ROUTER OF REFERRERS (the captain, 2026-09-13: \"QPU is basically intelligent router of referrers\", \"intelligence decides lean where processes is computed in realtime\").</td><td><code>qpuSeatsAvailableHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13613\"><code>qpuSeoOf</code></a></td><td>builder</td><td>The reading a caller can check: what this unit serves for one host, and the canonical door it points every host at.</td><td><code>qpuSeoHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L8153\"><code>qpuServerMcpOf</code></a></td><td>builder</td><td>The server sub-server's catalogue: eight tools, the job queue and the backend.</td><td><code>qpuServerMcpHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L8004\"><code>qpuServerSubmitOf</code></a></td><td>builder</td><td>Submit a job to the server: runs it on the exact computer and returns the result inline (jobs are not stored).</td><td><code>qpuServerSubmitHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L8052\"><code>qpuServerToolsOf</code></a></td><td>builder</td><td>The server MCP tools (submit, queue, result, backends and the rest) for jobs on the exact computer.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L2495\"><code>qpuShorOf</code></a></td><td>builder</td><td>Shor on the sparse exact state vector.</td><td><code>qpuShorHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L2482\"><code>qpuShorTryOf</code></a></td><td>builder</td><td>Shor as a caller asked for it: the run on their n and a, whatever they are.</td><td><code>qpuShorTryHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13567\"><code>qpuSitemapOf</code></a></td><td>builder</td><td>sitemap.xml for one first-party host — only URLs on that host, because a crawler ignores the rest.</td><td><code>qpuSitemapHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10299\"><code>qpuSpecServerOf</code></a></td><td>builder</td><td>The server a document declares, which is where its methods actually live.</td><td><code>qpuSpecServerHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L9607\"><code>qpuStandardsOf</code></a></td><td>builder</td><td>WHAT THIS TREE HOLDS ITSELF TO, SERVED RATHER THAN RUN BY HAND.</td><td><code>qpuStandardsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L5628\"><code>qpuStepsOf</code></a></td><td>builder</td><td>AUTONOMOUS STEPS, COMPUTED FROM THE LATTICE (the captain, 2026-09-12).</td><td><code>qpuStepsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L5323\"><code>qpuSubCatalogOf</code></a></td><td>builder</td><td>A sub-server's JSON-LD WebAPI catalogue: its tools as SoftwareApplication items and an ItemList.</td><td><code>qpuSubCatalogHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L5251\"><code>qpuSubManOf</code></a></td><td>builder</td><td>A man page for a sub-server tool (storage, network, server), synopsis on that server's href.</td><td><code>qpuSubManHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L14147\"><code>qpuToolsOf</code></a></td><td>builder</td><td>The eight qpu tools (quantum, lean, cite, train, improve, compete, forge, prove) with schemas, man pages and handlers.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12694\"><code>qpuTrainLiveOf</code></a></td><td>builder</td><td>qpu_train with live CERN occupancy and the live API composition.</td><td><code>qpuTrainLiveHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L11005\"><code>qpuTrainOf</code></a></td><td>builder</td><td>Two teams of seven agents run the lattice walk: steps, challenges, sandbox tools and the next door to call.</td><td><code>qpuTrainHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L6886\"><code>raidJoinOf</code></a></td><td>builder</td><td>The stripes read back in the order they were dealt — the inverse of raidStripeOf, collected and joined once.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L6874\"><code>raidStripeOf</code></a></td><td>builder</td><td>Exported for the property that used to be sampled on every write: raidJoinOf is the inverse of raidStripeOf, and dealing into rays can only differ by length modulo rays, so the claim is a cross product of residue against ray count.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L471\"><code>rpcErrorOf</code></a></td><td>builder</td><td>A JSON-RPC 2.0 error, as the protocol spells it: <code>jsonrpc</code>, the request's <code>id</code> (null when none was understood), and an <code>error</code> with code and message.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L2471\"><code>shorArgsOf</code></a></td><td>builder</td><td>Modulus and base as the caller gave them, read as integers, with how each was read.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L2427\"><code>shorDefaultsOf</code></a></td><td>builder</td><td>The modulus and base Shor runs on when the caller names none: faces.rays * (n * n + n + seed) = 91 and mintOf n = 8.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L3818\"><code>shorFactorOf</code></a></td><td>builder</td><td>The factoring claim computed from the run: the modulus Shor factored in this unit's exact state-vector computation — by default 91, the instance theorem shor states.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13296\"><code>bootPort</code></a></td><td>function</td><td>The one declaration of the port a booted unit serves on: boot.ts listens on $PORT, else this; the install manifest's docker command publishes it.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L14516\"><code>isUnknownTool</code></a></td><td>function</td><td>Type guard for the reply to a tools/call that names no tool of this unit.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L9927\"><code>qpuCallOfUuid</code></a></td><td>function</td><td>qpuCallOfUuid(uuid) → the combination that address names: the door, the pair, and whether it verifies.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L15310\"><code>HEX_PARAM_MODES</code></a></td><td>constant</td><td>How the params section splits: by the two free bits of the variant nibble.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13034\"><code>MCP_VERSIONS</code></a></td><td>constant</td><td>MCP protocol versions the /mcp door negotiates.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10652\"><code>QPU_EXPERIMENTS</code></a></td><td>constant</td><td>MIXED EXPERIMENTS: one experiment standing in two domains, and which of them taught the other.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1485\"><code>QPU_ZONE_HOSTS</code></a></td><td>constant</td><td>THE ZONE, HOST BY HOST — and every one of these names reaches this unit.</td><td>—</td><td>—</td></tr>\n</table>\n<p>Generated from the inline docs by <code>npm run docs</code>. Index: <a href=\"README.html\">docs</a>.</p>\n</body></html>\n","/science.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Live science data — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/science.html\">\n<meta name=\"description\" content=\"CERN Open Data, research APIs and citations read live with deadlines. 21 capabilities; 10 of 17 evidence predicates hold.\">\n<meta property=\"og:title\" content=\"Live science data — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"CERN Open Data, research APIs and citations read live with deadlines. 21 capabilities; 10 of 17 evidence predicates hold.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/science.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Live science data\">\n<meta name=\"twitter:description\" content=\"CERN Open Data, research APIs and citations read live with deadlines. 21 capabilities; 10 of 17 evidence predicates hold.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>Live science data</h1>\n<p>CERN Open Data, research APIs and citations read live with deadlines.</p>\n<table>\n<tr><th></th><th></th></tr>\n<tr><td>Capabilities</td><td>21</td></tr>\n<tr><td>With an evidence predicate</td><td>17</td></tr>\n<tr><td>Predicates that hold now</td><td>10</td></tr>\n<tr><td>Live (need the network; checked by the live doors)</td><td>7</td></tr>\n</table>\n<table>\n<tr><th>Capability</th><th>Kind</th><th>What it does</th><th>Evidence</th><th>Status</th></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L11713\"><code>qpuCernCatalogsOf</code></a></td><td>builder</td><td>The CERN catalogues the unit reads (Open Data, LHC experiments), with their hosts and paths.</td><td><code>qpuCernCatalogsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12674\"><code>qpuCernExperienceOf</code></a></td><td>builder</td><td>The live CERN reading, kept for one deadline window so a miss is not re-paid on every call.</td><td><code>qpuCernExperienceHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L11736\"><code>qpuCernExperimentsOf</code></a></td><td>builder</td><td>LHC experiments seated on faces, with the views (LHC, Open Data) they share.</td><td><code>qpuCernExperimentsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12006\"><code>qpuCernFetchOf</code></a></td><td>builder</td><td>Fetch one CMS Open Data record live and compare events, files, DOI and dates with the cern theorem.</td><td><code>qpuCernFetchHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12545\"><code>qpuCernLearnLiveOf</code></a></td><td>builder</td><td>The live CERN reading: every LHC and Open Data experiment's record total fetched under one deadline.</td><td><code>qpuCernLearnLiveHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L11904\"><code>qpuCernLearnOf</code></a></td><td>builder</td><td>The offline CERN reading: experiments and catalogues as an occupancy lattice.</td><td><code>qpuCernLearnHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12593\"><code>qpuCernLiveOf</code></a></td><td>builder</td><td>The live CERN document: quoted records, projects and search, fetched under one deadline.</td><td><code>qpuCernLiveHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12192\"><code>qpuCernOf</code></a></td><td>builder</td><td>The CERN document: quoted records, catalogues, experiments and the occupancy lattice.</td><td><code>qpuCernHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12115\"><code>qpuCernProjectFetchOf</code></a></td><td>builder</td><td>Fetch one experiment's record total live from CERN Open Data.</td><td><code>qpuCernProjectFetchHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10497\"><code>qpuCitationsLiveOf</code></a></td><td>builder</td><td>Resolve the corpus's DOIs through Crossref and check each title matches.</td><td><code>qpuCitationsLiveHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10443\"><code>qpuCitationsOf</code></a></td><td>builder</td><td>THE CITATIONS, AS IDENTIFIERS A MACHINE CAN RESOLVE RATHER THAN STRINGS A READER MIGHT.</td><td><code>qpuCitationsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L142\"><code>qpuForeignReadsOf</code></a></td><td>builder</td><td>How many times this process has read a host it does not own (CERN, Crossref, registries).</td><td><code>qpuForeignReadsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12870\"><code>qpuResearchFetchOf</code></a></td><td>builder</td><td>Fetch a research API (INSPIRE, HEPData, Zenodo) live and count its hits.</td><td><code>qpuResearchFetchHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10918\"><code>qpuTeachingCensusOf</code></a></td><td>builder</td><td>THE WHOLE CENSUS, so \"all entanglements\" is a number and not a gesture.</td><td><code>qpuTeachingCensusHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L9659\"><code>qpuTeachingPairsOf</code></a></td><td>builder</td><td>Teaching corpus crossed: subjects against domains, each pair entangled, application or undecided, with citations.</td><td><code>qpuTeachingPairsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10965\"><code>qpuTeachingReadingOf</code></a></td><td>builder</td><td>THE EXPLANATION, GENERATED FROM THE EVIDENCE RATHER THAN WRITTEN BESIDE IT.</td><td><code>qpuTeachingReadingHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10804\"><code>qpuTeachingSeatingOf</code></a></td><td>builder</td><td>SEATED BY THE EVIDENCE, NOT BY THE AUTHOR'S ORDERING.</td><td><code>qpuTeachingSeatingHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L11696\"><code>qpuCernCatalogsHold</code></a></td><td>function</td><td>THE CATALOGS ARE NOT THE FACES.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L9651\"><code>QPU_TEACHING_DOMAINS</code></a></td><td>constant</td><td>The distinct domains of the teaching corpus, sorted; the axis the corpus is crossed on.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L9645\"><code>QPU_TEACHING_SUBJECTS</code></a></td><td>constant</td><td>The corpus's own axes, named once: the combinatorial surface is built on these and the reading checks them.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L9278\"><code>QPU_TEACHINGS</code></a></td><td>constant</td><td>THE EVIDENCE.</td><td>—</td><td>—</td></tr>\n</table>\n<p>Generated from the inline docs by <code>npm run docs</code>. Index: <a href=\"README.html\">docs</a>.</p>\n</body></html>\n","/fusion.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>API fusion — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/fusion.html\">\n<meta name=\"description\" content=\"Every API in a registry crossed on field UUIDs into compositions, formulas and a graph state. 16 capabilities; 2 of 8 evidence predicates hold.\">\n<meta property=\"og:title\" content=\"API fusion — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"Every API in a registry crossed on field UUIDs into compositions, formulas and a graph state. 16 capabilities; 2 of 8 evidence predicates hold.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/fusion.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"API fusion\">\n<meta name=\"twitter:description\" content=\"Every API in a registry crossed on field UUIDs into compositions, formulas and a graph state. 16 capabilities; 2 of 8 evidence predicates hold.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>API fusion</h1>\n<p>Every API in a registry crossed on field UUIDs into compositions, formulas and a graph state.</p>\n<table>\n<tr><th></th><th></th></tr>\n<tr><td>Capabilities</td><td>16</td></tr>\n<tr><td>With an evidence predicate</td><td>8</td></tr>\n<tr><td>Predicates that hold now</td><td>2</td></tr>\n<tr><td>Live (need the network; checked by the live doors)</td><td>3</td></tr>\n</table>\n<table>\n<tr><th>Capability</th><th>Kind</th><th>What it does</th><th>Evidence</th><th>Status</th></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/mcp/cross-domain-formulas.ts#L34\"><code>crossFormulaOf</code></a></td><td>builder</td><td>Seal a cross formula: content UUID of {src, dst, formula}, holds (inputs in domain, value finite) and a quantum receipt in the cross stream.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/mcp/cross-domain-paths.ts#L27\"><code>domainPathOf</code></a></td><td>builder</td><td>Seal a multi-hop path: content UUID of {hops, formula} and a quantum receipt in the path stream.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/mcp/cross-domain-paths.ts#L141\"><code>pathHexOf</code></a></td><td>builder</td><td>The hex program that returns a named path. @wing fusion @kind function</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10378\"><code>qpuApisLiveOf</code></a></td><td>builder</td><td>The registry, the schemas and the methods, discovered live and bounded to <code>faces</code> schemas from an offset.</td><td><code>qpuApisLiveHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10233\"><code>qpuComposeLiveOf</code></a></td><td>builder</td><td>DISCOVERED AND CROSSED IN ONE CALL, so a door can carry the finding rather than the ingredients.</td><td><code>qpuComposeLiveHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10208\"><code>qpuComposeOf</code></a></td><td>builder</td><td>Cross API methods into compositions (entangled, application, undecided) joined on field shape UUIDs.</td><td><code>qpuComposeHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10588\"><code>qpuCrossOf</code></a></td><td>builder</td><td>The swap criterion over rows: a pair is entangled when each gives what the other takes, application when one way, undecided otherwise.</td><td><code>qpuCrossHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10112\"><code>qpuFuseOf</code></a></td><td>builder</td><td>Fuse API methods by an inverted field-UUID index: an edge is a giver and a taker of one field; edges carry direction, counts and the rarest field per direction; hubs ranked by giver x taker.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10160\"><code>qpuGraphStateOf</code></a></td><td>builder</td><td>THE FUSED GRAPH IS A GRAPH STATE.</td><td><code>qpuGraphStateHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10318\"><code>qpuProbeableOf</code></a></td><td>builder</td><td>Probeable when nothing must be supplied and nothing is written: no path template, no required parameter.</td><td><code>qpuProbeableHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10331\"><code>qpuProbeLiveOf</code></a></td><td>builder</td><td>Probe discovered APIs live with argument-free GET and POST calls and report which answer.</td><td><code>qpuProbeLiveHolds</code></td><td>live (network)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L10051\"><code>qpuSchemaMethodsOf</code></a></td><td>builder</td><td>An OpenAPI document read as methods: what each one takes, and what it gives back.</td><td><code>qpuSchemaMethodsHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/mcp/cross-domain-formulas.ts#L172\"><code>crossDomainFormulas</code></a></td><td>function</td><td>A CrossDomainFormulas instance.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/mcp/cross-domain-paths.ts#L135\"><code>crossDomainPaths</code></a></td><td>function</td><td>A CrossDomainPaths instance.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/mcp/cross-domain-formulas.ts#L54\"><code>CrossDomainFormulas</code></a></td><td>class</td><td>The ten named cross-domain bridges (each a CrossFormula) and allBridges(), their transforms over plain inputs.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/mcp/cross-domain-paths.ts#L37\"><code>CrossDomainPaths</code></a></td><td>class</td><td>The seven named multi-hop paths across domains, each with its hops, formula and transform.</td><td>—</td><td>—</td></tr>\n</table>\n<p>Generated from the inline docs by <code>npm run docs</code>. Index: <a href=\"README.html\">docs</a>.</p>\n</body></html>\n","/cms.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Payload & Cloudflare — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/cms.html\">\n<meta name=\"description\" content=\"Payload CMS on Workers in every combination, and the Payload readings the unit serves. 15 capabilities; 3 of 4 evidence predicates hold.\">\n<meta property=\"og:title\" content=\"Payload & Cloudflare — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"Payload CMS on Workers in every combination, and the Payload readings the unit serves. 15 capabilities; 3 of 4 evidence predicates hold.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/cms.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Payload & Cloudflare\">\n<meta name=\"twitter:description\" content=\"Payload CMS on Workers in every combination, and the Payload readings the unit serves. 15 capabilities; 3 of 4 evidence predicates hold.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>Payload &amp; Cloudflare</h1>\n<p>Payload CMS on Workers in every combination, and the Payload readings the unit serves.</p>\n<table>\n<tr><th></th><th></th></tr>\n<tr><td>Capabilities</td><td>15</td></tr>\n<tr><td>With an evidence predicate</td><td>4</td></tr>\n<tr><td>Predicates that hold now</td><td>3</td></tr>\n<tr><td>Live (need the network; checked by the live doors)</td><td>0</td></tr>\n</table>\n<table>\n<tr><th>Capability</th><th>Kind</th><th>What it does</th><th>Evidence</th><th>Status</th></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/deployment/payload-templates.ts#L382\"><code>cloudflareCombinationOf</code></a></td><td>builder</td><td>Parse a combination key (runtime/db/storage/email/plugins) back into a combination.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/deployment/payload-templates.ts#L375\"><code>cloudflareKeyOf</code></a></td><td>builder</td><td>A combination's canonical key: the axes in order, plugins sorted — what its content UUID is taken over.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/deployment/payload-templates.ts#L528\"><code>cloudflarePayloadOf</code></a></td><td>builder</td><td>Generate one combination: payload.config.ts, wrangler.jsonc and dependencies, optionally carrying an app's own collections (CloudflareApp).</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L14011\"><code>qpuFusionOf</code></a></td><td>builder</td><td>Fusion of catalogues, hosts, schemas, Payload, install and hologram readings over the fused capacity.</td><td><code>qpuFusionHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L14068\"><code>qpuIntelligenceOf</code></a></td><td>builder</td><td>The 'intelligence' reading: the fusion test over free online research.</td><td><code>qpuIntelligenceHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13802\"><code>qpuPayloadFindOf</code></a></td><td>builder</td><td>One Payload collection's find tool, sealed against writes.</td><td><code>qpuPayloadFindHolds</code></td><td>checked on each call (needs inputs)</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13757\"><code>qpuPayloadMcpOf</code></a></td><td>builder</td><td>The Payload MCP the unit describes: collections, find-only tools, the database plugin and its write path.</td><td><code>qpuPayloadMcpHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/deployment/payload-templates.ts#L547\"><code>cloudflareCombinations</code></a></td><td>function</td><td>Every combination of the axes: runtimes × databases × storage × email × every subset of the plugins.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/deployment/payload-templates.ts#L561\"><code>payloadTemplates</code></a></td><td>function</td><td>A PayloadTemplates instance.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/deployment/payload-templates.ts#L44\"><code>PayloadTemplates</code></a></td><td>class</td><td>Deployment templates: four hardware modes (browser, standalone, docker, kubernetes) and the Cloudflare family (cloudflarePayload) for Next.js + Payload on Workers.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/deployment/payload-templates.ts#L341\"><code>CLOUDFLARE_DATABASES</code></a></td><td>constant</td><td>qpu-raid and qpu-d1 are the QPU document database (MongoDB semantics) on native bindings: a MongoDB request on Workers is one of these.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/deployment/payload-templates.ts#L353\"><code>CLOUDFLARE_EMAIL</code></a></td><td>constant</td><td>Email choices: Resend, or none.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/deployment/payload-templates.ts#L359\"><code>CLOUDFLARE_PLUGINS</code></a></td><td>constant</td><td>The Payload plugins a combination can include.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/deployment/payload-templates.ts#L335\"><code>CLOUDFLARE_RUNTIMES</code></a></td><td>constant</td><td>Next.js runtimes on Workers: vinext (Cloudflare's recommended path) and the OpenNext adapter.</td><td>—</td><td>—</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/deployment/payload-templates.ts#L347\"><code>CLOUDFLARE_STORAGE</code></a></td><td>constant</td><td>Upload storage choices: R2, S3, or none.</td><td>—</td><td>—</td></tr>\n</table>\n<p>Generated from the inline docs by <code>npm run docs</code>. Index: <a href=\"README.html\">docs</a>.</p>\n</body></html>\n","/presentation.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Presentation & discovery — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/presentation.html\">\n<meta name=\"description\" content=\"Stylesheets, schemas, SEO zones, citation and the documents a reader or crawler sees. 14 capabilities; 14 of 14 evidence predicates hold.\">\n<meta property=\"og:title\" content=\"Presentation & discovery — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"Stylesheets, schemas, SEO zones, citation and the documents a reader or crawler sees. 14 capabilities; 14 of 14 evidence predicates hold.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/presentation.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Presentation & discovery\">\n<meta name=\"twitter:description\" content=\"Stylesheets, schemas, SEO zones, citation and the documents a reader or crawler sees. 14 capabilities; 14 of 14 evidence predicates hold.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>Presentation &amp; discovery</h1>\n<p>Stylesheets, schemas, SEO zones, citation and the documents a reader or crawler sees.</p>\n<table>\n<tr><th></th><th></th></tr>\n<tr><td>Capabilities</td><td>14</td></tr>\n<tr><td>With an evidence predicate</td><td>14</td></tr>\n<tr><td>Predicates that hold now</td><td>14</td></tr>\n<tr><td>Live (need the network; checked by the live doors)</td><td>0</td></tr>\n</table>\n<table>\n<tr><th>Capability</th><th>Kind</th><th>What it does</th><th>Evidence</th><th>Status</th></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1061\"><code>qpuAccessOf</code></a></td><td>builder</td><td>Access keys (domain, occupancy) for every occupancy, with their fused names.</td><td><code>qpuAccessHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L4946\"><code>qpuCiteOf</code></a></td><td>builder</td><td>How to cite the unit (MLA 8): DOI, concept DOI, ORCID, archived version and commit, served version, and whether they match.</td><td><code>qpuCiteHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12275\"><code>qpuCssOf</code></a></td><td>builder</td><td>The fused stylesheet the unit serves (qpu.css), with its size against the naive stylesheet.</td><td><code>qpuCssHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L766\"><code>qpuGenesisOf</code></a></td><td>builder</td><td>The UI schema: shadcn card variants, sizes, states and themes seated on the lattice's faces and rays, served as data (no HTML).</td><td><code>qpuGenesisHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1087\"><code>qpuHologramOf</code></a></td><td>builder</td><td>The 'hologram' reading: the pentagram and access readings composed with the fused capacity and the STORAGE/BLOBS bindings.</td><td><code>qpuHologramHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L894\"><code>qpuPentagramOf</code></a></td><td>builder</td><td>The occupancy pentagram: five occupancies x five skills joined in a single stroke of step 2.</td><td><code>qpuPentagramHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L6606\"><code>qpuPresenceOf</code></a></td><td>builder</td><td>Presence of users per face (active, inactive, chatting) with starter templates, merged into storage.</td><td><code>qpuPresenceHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L12490\"><code>qpuReflectOf</code></a></td><td>builder</td><td>Reflect a caller's text onto a face and its involution hop, with the stylesheet slots it occupies.</td><td><code>qpuReflectHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13524\"><code>qpuRobotsOf</code></a></td><td>builder</td><td>robots.txt for one first-party host — the zone's content-signal policy, and the one sitemap that host serves.</td><td><code>qpuRobotsHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L3469\"><code>qpuSchemasOf</code></a></td><td>builder</td><td>The JSON-LD schemas the unit serves, mounted under storage, with their prefixes and context.</td><td><code>qpuSchemasHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L13654\"><code>qpuSeoZoneOf</code></a></td><td>builder</td><td>SEO zone fields for each host: robots, sitemap and the zone's reserved labels.</td><td><code>qpuSeoZoneHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1557\"><code>qpuTenantZoneOf</code></a></td><td>builder</td><td>The tenant zone QPU serves and the labels in it that are never a tenant — one declaration, read by the router and by Payload (src/access.ts), never restated there.</td><td><code>qpuTenantZoneHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1534\"><code>qpuZoneHostOf</code></a></td><td>builder</td><td>The first-party host this request landed on, or undefined — and <code>qpu: false</code> is as good as absent here.</td><td><code>qpuZoneHostHolds</code></td><td>holds</td></tr>\n<tr><td><a href=\"https://github.com/uuidna/qpu/blob/main/src/quantum/processing/unit/index.ts#L1500\"><code>qpuZoneOf</code></a></td><td>builder</td><td>The zone with each first-party host resolved from its label — the apex carries the empty label and is the zone.</td><td><code>qpuZoneHolds</code></td><td>holds</td></tr>\n</table>\n<p>Generated from the inline docs by <code>npm run docs</code>. Index: <a href=\"README.html\">docs</a>.</p>\n</body></html>\n","/comparison.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Comparison — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/comparison.html\">\n<meta name=\"description\" content=\"What @uuidna/qpu does, wing by wing, beside quantum SDKs and simulators (Qiskit Aer, Cirq, Amazon Braket, PennyLane) and general AI models.\">\n<meta property=\"og:title\" content=\"Comparison — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"What @uuidna/qpu does, wing by wing, beside quantum SDKs and simulators (Qiskit Aer, Cirq, Amazon Braket, PennyLane) and general AI models.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/comparison.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Comparison\">\n<meta name=\"twitter:description\" content=\"What @uuidna/qpu does, wing by wing, beside quantum SDKs and simulators (Qiskit Aer, Cirq, Amazon Braket, PennyLane) and general AI models.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>Comparison</h1>\n<p>Rows are capability classes; a cell says what the system documents, not a benchmark. The qpu column is generated from this repository (receipts and evidence predicates); the others cite the vendor documentation listed below. qpu runs no physical quantum hardware.</p>\n<table>\n<tr><th>Capability</th><th>qpu</th><th>Qiskit Aer</th><th>Cirq</th><th>Amazon Braket</th><th>PennyLane</th><th>AI models (LLMs)</th></tr>\n<tr><td>Exact state vector</td><td>integer amplitudes, 3-qubit register (dim 8); sparse states, Shor on 9 qubits (dim 512)</td><td>statevector (dense, GPU)</td><td>state vector; qsim</td><td>SV1, up to 34 qubits</td><td>lightning.qubit / .gpu / .kokkos</td><td>none</td></tr>\n<tr><td>Noise / density matrix</td><td>XX noise identity only</td><td>noise models, density matrix</td><td>density matrix</td><td>DM1, up to 17 qubits</td><td>default.mixed</td><td>none</td></tr>\n<tr><td>Stabilizer / large structured states</td><td>graph state of the fused API registry, 2529 qubits, exact entanglement by GF(2) rank</td><td>stabilizer, extended stabilizer, MPS</td><td>Clifford simulator</td><td>TN1, up to 50 qubits</td><td>lightning.tensor (MPS)</td><td>none</td></tr>\n<tr><td>Physical hardware</td><td>none</td><td>IBM Quantum</td><td>Google Quantum AI (by access)</td><td>IonQ, Rigetti, IQM, QuEra and others</td><td>via plugins</td><td>none</td></tr>\n<tr><td>Formal proof</td><td>124 Lean 4 theorems, all served and recomputed (124/124)</td><td>none</td><td>none</td><td>none</td><td>none</td><td>none</td></tr>\n<tr><td>Content-addressed results</td><td>RFC 9562 v8 UUIDs and chained quantum receipts on every computation</td><td>job ids</td><td>none</td><td>task ARNs</td><td>none</td><td>none</td></tr>\n<tr><td>Agent interface</td><td>MCP server (/mcp), 16 tools</td><td>SDK (Python)</td><td>SDK (Python)</td><td>SDK and API</td><td>SDK (Python)</td><td>call tools through MCP or function calling</td></tr>\n<tr><td>Document database</td><td>MongoDB query/update semantics on Cloudflare KV+R2 or D1, Payload adapter</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td></tr>\n<tr><td>API fusion</td><td>2529 APIs, 438299 composing pairs, 438299 cross formulas</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td></tr>\n<tr><td>CMS on the edge</td><td>98304 Next.js + Payload configurations on Workers</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td></tr>\n<tr><td>License</td><td>CC-BY-NC-ND-4.0 (non-commercial, no derivatives)</td><td>Apache-2.0</td><td>Apache-2.0</td><td>commercial service</td><td>Apache-2.0</td><td>per provider</td></tr>\n</table>\n<h2>Sources</h2>\n<li><a href=\"https://docs.aws.amazon.com/braket/latest/developerguide/choose-a-simulator.html\">Amazon Braket simulators</a></li>\n<li><a href=\"https://qiskit.org/ecosystem/aer/stubs/qiskit_aer.AerSimulator.html\">Qiskit Aer AerSimulator</a></li>\n<li><a href=\"https://pypi.org/project/cirq/\">Cirq</a></li>\n<li><a href=\"https://github.com/quantumlib/qsim\">qsim</a></li>\n<li><a href=\"https://pypi.org/project/PennyLane-Lightning/0.32.0\">PennyLane Lightning</a></li>\n<li><a href=\"https://modelcontextprotocol.io/\">Model Context Protocol</a></li>\n<p>Live cross-checks of qpu's own claims against CERN, Zenodo, ORCID and NIST: 27 of 30 agree (see <a href=\"state.html\">state</a>).</p>\n</body></html>\n","/state.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>State — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/state.html\">\n<meta name=\"description\" content=\"Current state of @uuidna/qpu 1.0.0: what is built, what is verified, and what is open.\">\n<meta property=\"og:title\" content=\"State — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"Current state of @uuidna/qpu 1.0.0: what is built, what is verified, and what is open.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/state.html\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"State\">\n<meta name=\"twitter:description\" content=\"Current state of @uuidna/qpu 1.0.0: what is built, what is verified, and what is open.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>State</h1>\n<p>Version <strong>1.0.0</strong> (version lock: <code>v1.&lt;minor>.&lt;digit></code>, 0 = LTS; <a href=\"https://github.com/uuidna/qpu/blob/main/scripts/version-lock.mjs\">scripts/version-lock.mjs</a>).</p>\n<table>\n<tr><th>Measure</th><th>Value</th><th>Source</th></tr>\n<tr><td>Capabilities documented inline</td><td>245 of 247 exports</td><td><a href=\"https://github.com/uuidna/qpu/blob/main/scripts/generate-docs.mjs\">scripts/generate-docs.mjs</a></td></tr>\n<tr><td>Evidence predicates that hold</td><td>117 of 149 (live ones need the network)</td><td>evaluated by <code>npm run docs</code></td></tr>\n<tr><td>Lean theorems served / recomputed</td><td>124 / 124 of 124</td><td><a href=\"https://github.com/uuidna/qpu/blob/main/lean-receipt.json\">lean-receipt.json</a></td></tr>\n<tr><td>API registry fused</td><td>2529 of 2529 APIs, 438299 cross formulas</td><td><a href=\"https://github.com/uuidna/qpu/blob/main/fuse-receipt.json\">fuse-receipt.json</a></td></tr>\n<tr><td>Payload on Cloudflare</td><td>98304 combinations, 96 of 96 bases type-check</td><td><a href=\"https://github.com/uuidna/qpu/blob/main/payload-cf-receipt.json\">payload-cf-receipt.json</a></td></tr>\n<tr><td>Live cross-proof</td><td>27 of 30 claims agree; differ: zenodo latest archive, orcid family name, tc niobium mK</td><td><a href=\"https://github.com/uuidna/qpu/blob/main/cross-receipt.json\">cross-receipt.json</a></td></tr>\n</table>\n<h2>Open</h2>\n<li><strong>Live host is behind main.</strong> Cloudflare Workers Builds for the uuidna-qpu Worker has failed on every commit since 2026-10-01, so qpu.uuidna.com still serves v0.2.1. A clean clone of main installs, builds and passes <code>wrangler deploy --dry-run</code> (the unit bundles at 526 KiB with the STORAGE, BLOBS and PAYLOAD bindings); the failing step is in the Workers project's dashboard build settings, which this repository does not hold. Evidence: the Workers Builds check run on each commit; <code>npx wrangler deploy --dry-run</code>.</li>\n<li><strong>1.0.0 is not on npm.</strong> v1.0.0 has a GitHub release and a Zenodo record (10.5281/zenodo.23091364) but npm's latest is 0.2.1. The version lock forbids any bump until 1.0.0 is published: run publish.yml by workflow_dispatch from main; it needs a trusted publisher for publish.yml on npmjs.com. Evidence: <code>consolidatedMCP.executeWorkflow('release-workflow', { version: '1.0.0' })</code> reads npm, GitHub and Zenodo.</li>\n<li><strong>Two GitHub workflows still fail.</strong> ci-cd.yml and wave2-sdk-release.yml fail on push and have not been examined here. ci.yml was invalid YAML (a plain scalar holding <code>: </code>) and is fixed; its gate now resolves every operation by UUID and requires qpu_prove to hold. Evidence: GitHub Actions runs on main.</li>\n<li><strong>Two data discrepancies.</strong> ORCID 0009-0000-7312-9778 records the family name Roustchev while the citation and Zenodo say Rouschev; index.lean sets niobium to 9200 mK while the cited reference table gives 9.26 K (theorem superconductivity would read gap niobium = 679, not 674). Evidence: cross-receipt.json.</li>\n<li><strong>QPU database limits.</strong> A collection scan reads at most 4 pages of 1000 keys per request on KV+R2; KV is eventually consistent (prefer the D1 store when a write must be read back at once); no transactions; localized-field queries and geo operators are refused. Evidence: src/quantum/processing/unit/docdb.ts and src/db/payload-qpu.ts.</li>\n<li><strong>Not yet run on Workers.</strong> The Payload adapter, the regenerated payload configs and the 98304 Payload-on-Cloudflare combinations are type-checked and run in Node; none has run on a deployed Worker against real D1, KV, R2 or Hyperdrive bindings. The restored admin dashboard has not been rendered in Payload 4's admin; src/payload/admin/config.tsx imports slate and is unused. Evidence: payload-cf-receipt.json.</li>\n<li><strong>qpu_lean is near its token budget.</strong> The efficiency invariant requires calling a door to cost fewer tokens than reading the tree; qpu_lean now serves all 100 theorems with their family graph at 11574 tokens against 11709 to read. A larger proof will need a paginated or summarised qpu_lean before it grows. Evidence: qpuEfficiencyOf().rows.</li>\n</body></html>\n","/":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Documentation — @uuidna/qpu</title>\n<link rel=\"canonical\" href=\"https://qpu.uuidna.com/\">\n<meta name=\"description\" content=\"@uuidna/qpu 1.0.0: an exact quantum processing unit served over MCP, with formal proofs, content-addressed receipts, a document database on Cloudflare and Payload CMS integration.\">\n<meta property=\"og:title\" content=\"Documentation — @uuidna/qpu\">\n<meta property=\"og:description\" content=\"@uuidna/qpu 1.0.0: an exact quantum processing unit served over MCP, with formal proofs, content-addressed receipts, a document database on Cloudflare and Payload CMS integration.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://qpu.uuidna.com/\">\n<meta property=\"og:image\" content=\"https://opengraph.githubassets.com/qpu/uuidna/qpu\">\n<meta property=\"og:site_name\" content=\"@uuidna/qpu\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Documentation\">\n<meta name=\"twitter:description\" content=\"@uuidna/qpu 1.0.0: an exact quantum processing unit served over MCP, with formal proofs, content-addressed receipts, a document database on Cloudflare and Payload CMS integration.\">\n<style>body{font:15px/1.55 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1a1a1a;background:#fff}table{border-collapse:collapse;width:100%;margin:1rem 0;font-size:13px}th,td{border:1px solid #ddd;padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:#f6f6f6}code{font:12px ui-monospace,monospace;background:#f3f3f3;padding:0 .2rem}@media(prefers-color-scheme:dark){body{background:#111;color:#e8e8e8}th{background:#1d1d1d}td,th{border-color:#333}code{background:#222}a{color:#8ab4ff}}</style>\n</head><body>\n<h1>@uuidna/qpu documentation</h1>\n<p>An exact quantum processing unit served over MCP at qpu.uuidna.com: integer-amplitude state vectors, Lean-checked theorems, content-addressed quantum receipts, a MongoDB-semantics document database on Cloudflare bindings, API fusion and Payload CMS on Workers. Every page is generated from the inline docs; every capability links to its source and its evidence.</p>\n<table>\n<tr><th>Wing</th><th>Capabilities</th><th>Evidence holds</th></tr>\n<tr><td><a href=\"lattice.html\">Lattice &amp; arithmetic</a></td><td>9</td><td>7 of 7</td></tr>\n<tr><td><a href=\"quantum.html\">Quantum computation</a></td><td>17</td><td>14 of 17</td></tr>\n<tr><td><a href=\"proof.html\">Formal proof (Lean)</a></td><td>12</td><td>4 of 4</td></tr>\n<tr><td><a href=\"crypto.html\">Cryptography</a></td><td>3</td><td>2 of 2</td></tr>\n<tr><td><a href=\"receipts.html\">UUIDs &amp; quantum receipts</a></td><td>39</td><td>15 of 17</td></tr>\n<tr><td><a href=\"storage.html\">Storage &amp; database</a></td><td>25</td><td>6 of 10</td></tr>\n<tr><td><a href=\"agents.html\">MCP &amp; agents</a></td><td>76</td><td>45 of 54</td></tr>\n<tr><td><a href=\"science.html\">Live science data</a></td><td>21</td><td>10 of 17</td></tr>\n<tr><td><a href=\"fusion.html\">API fusion</a></td><td>16</td><td>2 of 8</td></tr>\n<tr><td><a href=\"cms.html\">Payload &amp; Cloudflare</a></td><td>15</td><td>3 of 4</td></tr>\n<tr><td><a href=\"presentation.html\">Presentation &amp; discovery</a></td><td>14</td><td>14 of 14</td></tr>\n</table>\n<p>Also: <a href=\"state.html\">state</a> · <a href=\"comparison.html\">comparison</a> · <a href=\"https://github.com/uuidna/qpu/blob/main/README.md\">build receipt</a></p>\n<h2>Use</h2>\n<table>\n<tr><th>Command</th><th>Does</th></tr>\n<tr><td><code>npm run build</code></td><td>compile, after the version lock</td></tr>\n<tr><td><code>npm run lean</code></td><td>check index.lean with Lean 4</td></tr>\n<tr><td><code>npm run lean:embed</code></td><td>embed index.lean and the version into the unit</td></tr>\n<tr><td><code>npm run fuse</code></td><td>fuse the API registry</td></tr>\n<tr><td><code>npm run payload:cf</code></td><td>enumerate and type-check every Payload-on-Cloudflare combination (<code>-- --repo</code> regenerates this repo's configs)</td></tr>\n<tr><td><code>npm run readme</code></td><td>write the build receipt</td></tr>\n<tr><td><code>npm run docs</code></td><td>write these docs</td></tr>\n</table>\n</body></html>\n"}
